use std::path::PathBuf;
use std::time::Duration;

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{each, within, FlowError, Scope};
use lgwks_bot::task::{task, Host};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

const RUN_HEX: &str = "7c2f4a9e15b3d6084ea1c97f0b2d6358";

enum UnitOutcome {
    Done(u64),
    Failed(u32),
}

struct CancelOnDrop<'a>(&'a Host);

impl Drop for CancelOnDrop<'_> {
    fn drop(&mut self) {
        self.0.cancel();
    }
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let host = Host::builder("recover")
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let run = RunId::from_hex(RUN_HEX).map_err(|_| RecoveryError::NoStore)?;

    let task_world = world.clone();

    let task_body = move |scope: Scope, _input: ()| {
        let world = task_world.clone();
        async move {
            let count = world.stats().len() as u32;
            let root = scope.clone();

            let unit_body = {
                let world = world.clone();
                move |_item: Scope, index: u32| {
                    let world = world.clone();
                    let root = root.clone();
                    async move {
                        match world.unit(&root, index).await {
                            Ok(value) => Ok::<UnitOutcome, FlowError>(UnitOutcome::Done(value)),
                            Err(_) => Ok(UnitOutcome::Failed(index)),
                        }
                    }
                }
            };

            let raced = within(
                &scope,
                "overall",
                deadline,
                each(&scope, "units", None, 0u32..count, unit_body),
            )
            .await;

            let total: Result<u64, RecoveryError> = match raced {
                Ok(values) => {
                    let mut total: u64 = 0;
                    let mut failed: Option<u32> = None;
                    for value in values {
                        match value {
                            UnitOutcome::Done(v) => total += v,
                            UnitOutcome::Failed(i) => failed = Some(i),
                        }
                    }
                    match failed {
                        Some(index) => Err(RecoveryError::Unit { index }),
                        None => Ok(total),
                    }
                }
                Err(_) => Err(RecoveryError::Deadline),
            };

            Ok::<Result<u64, RecoveryError>, FlowError>(total)
        }
    };

    let run_task = task("recover", task_body).map_err(|_| RecoveryError::NoStore)?;

    let _guard = CancelOnDrop(&host);

    let report = host.resume(run, &run_task, ()).await;

    let outcome = match report.into_result() {
        Ok(inner) => inner,
        Err(_) => return Err(RecoveryError::Deadline),
    };

    match outcome {
        Ok(total) => {
            let ledger = world.ledger();
            if !ledger.applied("recover") {
                ledger.apply("recover");
            }
            Ok(total)
        }
        Err(error) => Err(error),
    }
}

use std::path::PathBuf;
use std::time::Duration;

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{FlowError, Scope, Tenant, within};
use lgwks_bot::task::{Disposition, Host, task};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

const TENANT: &str = "recovery";
const TASK: &str = "recover";
const EFFECT: &str = "recover";
const RUN_HEX: &str = "00000000000000000000000000000001";

async fn run_units(world: World, scope: Scope) -> Result<u64, FlowError> {
    let mut total: u64 = 0;
    let mut index: u32 = 0;
    loop {
        match world.unit(&scope, index).await {
            Ok(value) => {
                total = total.wrapping_add(value);
                match index.checked_add(1) {
                    Some(next) => index = next,
                    None => break,
                }
            }
            Err(_) => break,
        }
    }
    Ok(total)
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let ledger = match world.ledger() {
        Some(ledger) => ledger,
        None => return Err(RecoveryError::NoLedger),
    };
    if !ledger.applied(EFFECT) {
        ledger.apply(EFFECT);
    }

    let tenant = match Tenant::new(TENANT) {
        Ok(tenant) => tenant,
        Err(_) => return Err(RecoveryError::NoStore),
    };
    let root = Scope::root(tenant);

    let host = match Host::builder(TENANT) {
        Ok(builder) => builder,
        Err(_) => return Err(RecoveryError::NoStore),
    };
    let host = match host.run_store(store_dir) {
        Ok(builder) => builder,
        Err(_) => return Err(RecoveryError::NoStore),
    };
    let host = match host.default_deadline(deadline).build() {
        Ok(host) => host,
        Err(_) => return Err(RecoveryError::NoStore),
    };

    let run = match RunId::from_hex(RUN_HEX) {
        Ok(run) => run,
        Err(_) => return Err(RecoveryError::NoStore),
    };

    let task = match task(TASK, move |scope: Scope, _input: ()| run_units(world.clone(), scope)) {
        Ok(task) => task,
        Err(_) => return Err(RecoveryError::NoStore),
    };

    let attempt = host.resume(run, &task, ());
    let report = match within(&root, TASK, deadline, attempt).await {
        Ok(report) => report,
        Err(_) => return Err(RecoveryError::Deadline),
    };

    let disposition = report.disposition();
    match report.into_result() {
        Ok(total) => Ok(total),
        Err(error) => {
            if matches!(disposition, Disposition::DeadlineExceeded | Disposition::Cancelled)
                || error.is_cancelled()
            {
                Err(RecoveryError::Deadline)
            } else {
                Err(RecoveryError::Unit { index: 0 })
            }
        }
    }
}

use std::path::PathBuf;
use std::time::Duration;

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{FlowError, Scope};
use lgwks_bot::task::{task, Disposition, Host};

const TENANT: &str = "recovery";
const TASK_NAME: &str = "recover";
const EFFECT: &str = "recover";

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

async fn run_units(scope: Scope, world: World) -> Result<u64, FlowError> {
    let mut total: u64 = 0;
    let mut index: u32 = 0;
    loop {
        match world.unit(&scope, index).await {
            Ok(value) => {
                total = total.wrapping_add(value);
                match index.checked_add(1) {
                    Some(next) => index = next,
                    None => break,
                }
            }
            Err(_) => break,
        }
    }
    Ok(total)
}

fn hash_path(bytes: &[u8], seed: u64) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325u64 ^ seed;
    for &byte in bytes {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

fn run_identity(store_dir: &std::path::Path) -> RunId {
    let path = store_dir.to_string_lossy();
    let bytes = path.as_bytes();
    let hi = hash_path(bytes, 0x9e37_79b9_7f4a_7c15);
    let mut lo = hash_path(bytes, 0x517c_c1b7_2722_0a95);
    if hi == 0 && lo == 0 {
        lo = 1;
    }
    let text = format!("{hi:016x}{lo:016x}");
    RunId::from_hex(&text).expect("run identity is 32 lowercase hex digits")
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let run = run_identity(store_dir.as_path());

    let builder = Host::builder(TENANT).map_err(|_| RecoveryError::NoStore)?;
    let builder = builder
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?;
    let host = builder
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let unit_task = task(TASK_NAME, run_units).map_err(|_| RecoveryError::NoStore)?;

    let report = host.resume(run, &unit_task, world.clone()).await;

    let disposition = report.disposition();
    let outcome = report.into_result();
    match disposition {
        Disposition::Succeeded => {
            let total = outcome.unwrap_or(0);
            let ledger = world.ledger();
            if !ledger.applied(EFFECT) {
                ledger.apply(EFFECT);
            }
            Ok(total)
        }
        Disposition::DeadlineExceeded | Disposition::Cancelled => Err(RecoveryError::Deadline),
        _ => Err(RecoveryError::Unit { index: 0 }),
    }
}

use std::path::PathBuf;
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::Arc;
use std::time::Duration;

use ai_task_support::recovery::{UnitError, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{within, FlowError, Scope};
use lgwks_bot::task::{task, Disposition, Host};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

const RUN_HEX: &str = "00000000000000000000000000000001";

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let run = RunId::from_hex(RUN_HEX).map_err(|_| RecoveryError::NoLedger)?;

    let host = Host::builder("recovery")
        .map_err(|_| RecoveryError::NoLedger)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let failed = Arc::new(AtomicU32::new(u32::MAX));
    let flag = Arc::clone(&failed);

    let work = task("recover", move |scope: Scope, world: World| {
        let flag = Arc::clone(&flag);
        async move { run_units(world, scope, deadline, flag).await }
    })
    .map_err(|_| RecoveryError::NoLedger)?;

    let report = host.resume(run, &work, world).await;

    let disposition = report.disposition();
    match report.into_result() {
        Ok(total) => Ok(total),
        Err(error) => {
            let index = failed.load(Ordering::SeqCst);
            Err(classify(disposition, &error, index))
        }
    }
}

async fn run_units(
    world: World,
    scope: Scope,
    deadline: Duration,
    failed: Arc<AtomicU32>,
) -> Result<u64, FlowError> {
    let total = within(&scope, "overall", deadline, async {
        let mut total: u64 = 0;
        let mut index: u32 = 0;
        loop {
            match world.unit(&scope, index).await {
                Ok(value) => total = total.wrapping_add(value),
                Err(UnitError::Unit { index }) => {
                    failed.store(index, Ordering::SeqCst);
                    return Err(FlowError::failed("unit failed"));
                }
                Err(_) => break,
            }
            index = index.wrapping_add(1);
        }

        let ledger = world.ledger();
        if !ledger.applied("recover") {
            ledger.apply("recover");
        }

        Ok::<u64, FlowError>(total)
    })
    .await?;

    Ok(total)
}

fn classify(disposition: Disposition, error: &FlowError, index: u32) -> RecoveryError {
    if matches!(disposition, Disposition::DeadlineExceeded)
        || matches!(disposition, Disposition::Cancelled)
        || matches!(error, FlowError::TimedOut { .. })
        || matches!(error, FlowError::Cancelled { .. })
    {
        RecoveryError::Deadline
    } else {
        RecoveryError::Unit {
            index: if index == u32::MAX { 0 } else { index },
        }
    }
}

//! Crash-tolerant recovery: a durable run identity, a replaying run store, and a
//! ledger effect that is applied at most once across any number of attempts.

use std::future::Future;
use std::path::{Path, PathBuf};
use std::pin::Pin;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use ai_task_support::recovery::{UnitError, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{FlowError, Scope};
use lgwks_bot::task::{Host, Task, task};

/// Everything that can stop a recovery short of its total.
#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// The task body, boxed so one built value can drive both a first attempt and a
/// resume.
type Body = Pin<Box<dyn Future<Output = Result<u64, FlowError>> + Send>>;

/// The exact closure type `build_task` hands to `task`, so the returned
/// `Task<..>` is nameable and drives both the first attempt and the resume.
type Entry = Box<dyn Fn(Scope, ()) -> Body + Send + Sync>;

/// What the task body wants the caller told, when it cannot tell it itself.
#[derive(Clone, Copy)]
enum Fail {
    Unit(u32),
    Deadline,
}

/// Cancels the host if the `recover` future is dropped before the run settles.
struct CancelOnDrop(Arc<Host>);

impl Drop for CancelOnDrop {
    fn drop(&mut self) {
        self.0.cancel();
    }
}

/// A run identity derived from the store location, so every attempt at the same
/// store lands on the same run and finds the records left by the last one.
fn run_id(dir: &Path) -> RunId {
    use std::collections::hash_map::DefaultHasher;
    use std::hash::{Hash, Hasher};

    let mut hasher = DefaultHasher::new();
    dir.to_string_lossy().hash(&mut hasher);
    let seed = hasher.finish();

    for salt in 0u64..4 {
        let left = seed ^ salt.wrapping_mul(0x9e37_79b9_7f4a_7c15);
        let right = seed.rotate_left(17) ^ !salt;
        let text = format!("{:016x}{:016x}", left, right);
        if let Ok(id) = RunId::from_hex(&text) {
            return id;
        }
    }

    RunId::from_hex("5eed5eed5eed5eed5eed5eed5eed5eed").expect("a non-zero run identity")
}

/// Builds the recovery task once; the same value is used for the first attempt
/// and for every resume.
fn build_task(
    world: World,
    failed: Arc<Mutex<Option<Fail>>>,
    clock: (Instant, Duration),
) -> Result<Task<Entry>, FlowError> {
    let entry = move |scope: Scope, _input: ()| -> Body {
        let world = world.clone();
        let failed = Arc::clone(&failed);
        let clock = clock;
        Box::pin(async move {
            let (started, deadline) = clock;
            let mut total: u64 = 0;
            let mut index: u32 = 0;

            loop {
                // Only ever checked between units, so nothing is in flight when
                // the body returns.
                if started.elapsed() >= deadline {
                    *failed.lock().unwrap() = Some(Fail::Deadline);
                    return Err(FlowError::failed("recovery deadline reached"));
                }

                match world.unit(&scope, index).await {
                    Ok(value) => {
                        total = total.wrapping_add(value);
                        index += 1;
                    }
                    Err(UnitError::Unit { index: at }) => {
                        // A unit beyond the end of the world fails the same way a
                        // failing unit does, so look one further on: a unit there
                        // means this one is a real failure, nothing there means
                        // every unit has run.
                        if world.unit(&scope, index + 1).await.is_ok() {
                            *failed.lock().unwrap() = Some(Fail::Unit(at));
                            return Err(FlowError::failed("unit failed"));
                        }
                        break;
                    }
                }
            }

            if !world.ledger().applied("recover") {
                world.ledger().apply("recover");
            }

            Ok(total)
        })
    };

    task("recover", Box::new(entry) as Entry)
}

/// Drives the world to completion, resuming whatever a previous attempt recorded
/// and applying the ledger effect exactly once across all attempts.
pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let started = Instant::now();
    let run = run_id(&store_dir);

    let builder = Host::builder("recovery").map_err(|_| RecoveryError::NoStore)?;
    let builder = builder
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?;
    // The deadline is enforced between units rather than around them, so a cut
    // short never leaves a unit body running. The host's own bound is only a
    // backstop well past it.
    let host = builder
        .default_deadline(deadline.saturating_add(Duration::from_secs(86_400)))
        .build()
        .map_err(|_| RecoveryError::NoStore)?;
    let host = Arc::new(host);
    let _guard = CancelOnDrop(Arc::clone(&host));

    let failed: Arc<Mutex<Option<Fail>>> = Arc::new(Mutex::new(None));
    let task = build_task(world, Arc::clone(&failed), (started, deadline))
        .map_err(|_| RecoveryError::NoStore)?;

    let report = host.resume(run, &task, ()).await;
    let outcome = report.into_result();

    match outcome {
        Ok(total) => Ok(total),
        Err(err) => match *failed.lock().unwrap() {
            Some(Fail::Unit(index)) => Err(RecoveryError::Unit { index }),
            Some(Fail::Deadline) => Err(RecoveryError::Deadline),
            None => {
                if matches!(err, FlowError::TimedOut { .. }) || started.elapsed() >= deadline {
                    Err(RecoveryError::Deadline)
                } else {
                    Err(RecoveryError::NoLedger)
                }
            }
        },
    }
}

use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::Arc;
use std::time::Duration;

use ai_task_support::recovery::UnitError;
use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{self, FlowError, Scope};
use lgwks_bot::task::{self, Disposition, Host};

const TENANT: &str = "recovery";
const TASK_NAME: &str = "recover";
const EFFECT: &str = "recover";
const DEADLINE_STEP: &str = "deadline";
const NO_UNIT: u32 = u32::MAX;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// Owns the host for the length of one attempt. Dropping it — including by
/// dropping the future returned by `recover` part-way through — cancels the
/// attempt, so no unit body outlives the call.
struct Attempt {
    host: Host,
}

impl Drop for Attempt {
    fn drop(&mut self) {
        self.host.cancel();
    }
}

/// A run identity derived from the store directory: the same directory on every
/// attempt yields the same run, so a later attempt finds the earlier records,
/// and two different stores never share a run.
fn run_id_for(store_dir: &Path) -> Result<RunId, RecoveryError> {
    let mut low: u64 = 0xcbf2_9ce4_8422_2325;
    for byte in store_dir.to_string_lossy().as_bytes() {
        low ^= u64::from(*byte);
        low = low.wrapping_mul(0x0000_0100_0000_01b3);
    }
    let mut high: u64 = low.rotate_left(29) ^ 0x9e37_79b9_7f4a_7c15;
    if high == 0 {
        high = 1;
    }
    let low = if low == 0 { 1 } else { low };
    let hex = format!("{:016x}{:016x}", low, high);
    RunId::from_hex(&hex).map_err(|_| RecoveryError::NoStore)
}

/// One attempt under `run`. The task body is built once and reused by the first
/// attempt and every resume after it: each unit records its own value under its
/// own step path, so a resumed attempt replays completed units instead of
/// running their bodies again.
async fn attempt(
    host: &Host,
    run: RunId,
    world: World,
    deadline: Duration,
    failed: Arc<AtomicU32>,
) -> Result<u64, RecoveryError> {
    let body_world = world.clone();
    let body = move |scope: Scope, _input: ()| {
        let world = body_world.clone();
        let failed = Arc::clone(&failed);
        async move {
            let work = async {
                let mut total: u64 = 0;
                let mut index: u32 = 0;
                loop {
                    match world.unit(&scope, index).await {
                        Ok(value) => {
                            total = total.saturating_add(value);
                        }
                        Err(UnitError::Unit { index: bad }) => {
                            failed.store(bad, Ordering::SeqCst);
                            return Err::<u64, FlowError>(FlowError::failed("unit failed"));
                        }
                        // No unit at this index: the world is exhausted.
                        Err(_) => break,
                    }
                    index = index.saturating_add(1);
                }

                if !world.ledger().applied(EFFECT) {
                    world.ledger().apply(EFFECT);
                }

                Ok::<u64, FlowError>(total)
            };
            script::within(&scope, DEADLINE_STEP, deadline, work).await
        }
    };

    let task = task::task(TASK_NAME, body).map_err(|_| RecoveryError::NoStore)?;
    let report = host.resume(run, &task, ()).await;

    match report.disposition() {
        disposition if disposition.is_success() => {
            let total = match report.output() {
                Some(total) => *total,
                None => return Err(RecoveryError::NoLedger),
            };
            if world.ledger().applied(EFFECT) {
                Ok(total)
            } else {
                Err(RecoveryError::NoLedger)
            }
        }
        Disposition::DeadlineExceeded | Disposition::Cancelled => Err(RecoveryError::Deadline),
        _ => match report.error() {
            Some(err) if err.is_cancelled() => Err(RecoveryError::Deadline),
            _ => Err(RecoveryError::NoStore),
        },
    }
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let run = run_id_for(&store_dir)?;
    let _ = std::fs::create_dir_all(&store_dir);

    let host = Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(store_dir.as_path())
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let owner = Attempt { host };
    let failed = Arc::new(AtomicU32::new(NO_UNIT));
    let outcome = attempt(
        &owner.host,
        run,
        world.clone(),
        deadline,
        Arc::clone(&failed),
    )
    .await;
    drop(owner);

    let index = failed.load(Ordering::SeqCst);
    if index != NO_UNIT {
        return Err(RecoveryError::Unit { index });
    }

    outcome
}

//! Durable recovery for an `ai_task_support::recovery::World`.
//!
//! Nothing here assumes the platform cleans up after itself:
//!
//! * a guard cancels the host whenever the returned future is dropped, so no
//!   unit body can outlive the call, whatever the caller does with the future;
//! * the caller's deadline is raced *twice* — once by the host's own default
//!   deadline and once by an outer `within` — and either one dropping the body
//!   is followed by an explicit `cancel()` before the error is handed back;
//! * the ledger effect is guarded by an `applied` probe that is checked
//!   immediately before `apply`, with nothing awaited in between, so a resume
//!   can never apply it twice.
//!
//! The run identity is derived from the store's own path rather than drawn
//! fresh, so a second `recover` on the same `store_dir` finds the first
//! attempt's step records and replays them instead of re-running the bodies.

use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::{UnitError, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{FlowError, Scope, Tenant, within};
use lgwks_bot::task::{task, Host};

const TASK_NAME: &str = "recover";
const EFFECT_NAME: &str = "recover";
const TENANT: &str = "recovery";

/// Used only if the derived identity is somehow rejected by `from_hex`; it is
/// a valid, non-zero 32-character lowercase hex run id.
const FALLBACK_RUN: &str = "0123456789abcdef0123456789abcdef";

#[derive(Debug)]
#[allow(dead_code)]
pub enum RecoveryError {
    /// A unit failed; `index` is the unit the world named.
    Unit { index: u32 },
    /// The deadline passed before the work was finished.
    Deadline,
    /// The durable run store, its run identity, or the host that opens it
    /// could not be prepared.
    NoStore,
    /// The ledger effect could not be reached or guarded.
    NoLedger,
}

/// Cancels the host on drop, whether we finish normally, fail, or are dropped
/// mid-run. This is the only thing standing between a dropped caller and a
/// unit body that keeps running.
struct CancelOnDrop {
    host: Host,
}

impl Drop for CancelOnDrop {
    fn drop(&mut self) {
        self.host.cancel();
    }
}

/// Run every unit of `world` under `scope`, one at a time.
///
/// Each unit records itself durably under its own step, so a replayed unit
/// costs no body run and the sum below is the same on every attempt. The unit
/// the world names as failed, if any, is handed back through `failed` rather
/// than through the return type, which stays a recordable integer.
async fn replay_units(
    scope: Scope,
    world: World,
    failed: Arc<Mutex<Option<u32>>>,
) -> Result<u64, FlowError> {
    let mut total: u64 = 0;
    let mut index: u32 = 0;

    loop {
        if scope.is_cancelled() {
            // Stop before touching another unit; the effect is not applied.
            return Ok(total);
        }

        match world.unit(&scope, index).await {
            Ok(value) => {
                total = total.saturating_add(value);
                match index.checked_add(1) {
                    Some(next) => index = next,
                    None => break,
                }
            }
            // The world named a unit *behind* the one we probed. An index at
            // or past the probe is how the world reports that no unit is left,
            // but a name behind it can only mean an earlier unit failed.
            Err(UnitError::Unit { index: named }) if named < index => {
                if let Ok(mut slot) = failed.lock() {
                    *slot = Some(named);
                }
                return Ok(total);
            }
            // No unit at this index: the world's units have all run. Unless
            // the scope was cancelled, in which case there is more to do.
            Err(_) => {
                if scope.is_cancelled() {
                    return Ok(total);
                }
                break;
            }
        }
    }

    // Applied at most once across every attempt: the probe and the apply are
    // adjacent, with no await between them, so no other attempt can interleave.
    let ledger = world.ledger();
    if !ledger.applied(EFFECT_NAME) {
        ledger.apply(EFFECT_NAME);
    }

    Ok(total)
}

/// 32 lowercase hex characters, stable for a given store directory and
/// guaranteed non-zero.
fn run_hex(dir: &Path) -> String {
    let bytes = dir.to_string_lossy();
    let hi = fnv1a(bytes.as_bytes(), 0xcbf2_9ce4_8422_2325) | 1;
    let lo = fnv1a(bytes.as_bytes(), 0x9ae1_6a3b_2f90_404f);
    format!("{:016x}{:016x}", hi, lo)
}

fn fnv1a(bytes: &[u8], seed: u64) -> u64 {
    let mut hash = seed;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

/// The run identity every attempt on `dir` shares.
fn run_id(dir: &Path) -> Option<RunId> {
    let text = run_hex(dir);
    RunId::from_hex(&text)
        .ok()
        .or_else(|| RunId::from_hex(FALLBACK_RUN).ok())
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    // The store has to be there before a host can open it.
    fs::create_dir_all(&store_dir).map_err(|_| RecoveryError::NoStore)?;

    // One identity for every attempt on this store: derived from the store's
    // own path, never drawn fresh, so a later call finds the earlier records.
    let run = run_id(&store_dir).ok_or(RecoveryError::NoStore)?;

    // A host that keeps step records across attempts and enforces the caller's
    // deadline over the whole run on its own.
    let builder = Host::builder(TENANT).map_err(|_| RecoveryError::NoStore)?;
    let builder = builder
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline);
    let host = builder.build().map_err(|_| RecoveryError::NoStore)?;

    // Declared before anything is started: dropping this future drops the
    // guard, which cancels the host, which drops any live unit body.
    let guard = CancelOnDrop { host };

    // The name of a unit that failed is carried out of the body here, because
    // the body's own value has to stay a plain recordable integer.
    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let sink = Arc::clone(&failed);

    // The body is built once here and used by every attempt below.
    let task = task(TASK_NAME, move |scope: Scope, world: World| {
        let sink = Arc::clone(&sink);
        async move { replay_units(scope, world, sink).await }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    // The deadline is raced here as well as on the host, so the caller's budget
    // is honoured whichever side notices it first. Both timers have the same
    // budget, and the inner one starts later, so this is the binding clock.
    let outer = Scope::root(Tenant::new(TENANT).map_err(|_| RecoveryError::NoStore)?);

    // The body already yields `Result<u64, FlowError>`, so `within` hands back
    // that value directly: `Ok` only when the whole run completed in budget.
    let attempt = async {
        let host = &guard.host;
        host.resume(run, &task, world).await.into_result()
    };
    let finished = within(&outer, TASK_NAME, deadline, attempt).await;

    let total = match finished {
        Ok(total) => total,
        // Either the outer clock fired and dropped the run future, or the host
        // itself stopped the run. Cancel explicitly so that nothing is still
        // live when the error is handed back.
        Err(_) => {
            guard.host.cancel();
            return Err(RecoveryError::Deadline);
        }
    };

    if let Some(index) = failed.lock().ok().and_then(|slot| *slot) {
        return Err(RecoveryError::Unit { index });
    }

    Ok(total)
}

//! Crash-tolerant recovery of a run of world units.
//!
//! The identity of the run is derived from the store directory, so a second call
//! into the same store finds the records the first attempt committed instead of
//! starting a fresh run. The host that owns execution is wrapped in a guard whose
//! `Drop` cancels it: whether we finish, fail, or the caller drops our future,
//! the execution scope is cancelled and every live unit body is torn down.

use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::{UnitError, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{at_most, each, FlowError, Scope};
use lgwks_bot::task::{self, Disposition, Host};

/// Tenant and task name; both attempts share this step prefix, so the records a
/// unit commits land on the same paths every time.
const TASK_NAME: &str = "recover";
/// The step name the fan-out over the world's units runs under.
const UNITS_STEP: &str = "units";
/// The single effect this recovery commits.
const EFFECT: &str = "recover";
/// Upper bound on concurrently live unit bodies.
const FAN_OUT: usize = 8;
/// Attempts one call makes before reporting that it did not finish.
const MAX_ATTEMPTS: u32 = 3;

/// Everything `recover` can fail with.
#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// A run identity that is a pure function of the store directory: stable across
/// calls, so a later attempt replays the records an earlier attempt committed.
fn run_id(store_dir: &std::path::Path) -> Result<RunId, RecoveryError> {
    let mut hasher = DefaultHasher::new();
    store_dir.hash(&mut hasher);
    let mut digest = hasher.finish();
    if digest == 0 {
        // `RunId::from_hex` rejects an all-zero identity.
        digest = 1;
    }
    RunId::from_hex(&format!("{:016x}{:016x}", digest, digest)).map_err(|_| RecoveryError::NoStore)
}

/// Holds the host and cancels it on the way out, however we get out.
struct HostGuard(Host);

impl std::ops::Deref for HostGuard {
    type Target = Host;

    fn deref(&self) -> &Host {
        &self.0
    }
}

impl Drop for HostGuard {
    fn drop(&mut self) {
        self.0.cancel();
    }
}

/// The one body both attempts share. Built once per task, invoked per attempt.
async fn work(
    world: World,
    scope: Scope,
    failed: Arc<Mutex<Option<u32>>>,
    units: u32,
) -> Result<u64, FlowError> {
    let limit = at_most(FAN_OUT)?;
    let items: Vec<u32> = (0..units).collect();

    // The fan-out takes a clone; `world` itself stays here for the ledger, which
    // is outliving the bodies and must be readable once the fan-out is done.
    let fan_out_world = world.clone();

    // Each unit records its own value under `unit_step(index)`, so a recorded
    // unit replays instead of running its body again. `each` owns the bodies:
    // dropping this future drops every one still in flight.
    let values: Vec<u64> = each(&scope, UNITS_STEP, Some(limit), items, move |step, index| {
        let world = fan_out_world.clone();
        let failed = failed.clone();
        async move {
            match world.unit(&step, index).await {
                Ok(value) => Ok(value),
                Err(UnitError::Unit { index }) => {
                    if let Ok(mut slot) = failed.lock() {
                        *slot = Some(index);
                    }
                    Err(FlowError::failed("a world unit failed"))
                }
            }
        }
    })
    .await?;

    // The effect is committed exactly once, ever: both attempts read `applied`
    // first, and the ledger is shared across attempts.
    if !world.ledger().applied(EFFECT) {
        world.ledger().apply(EFFECT);
    }

    Ok(values.into_iter().sum())
}

fn clear_failed(failed: &Arc<Mutex<Option<u32>>>) {
    if let Ok(mut slot) = failed.lock() {
        *slot = None;
    }
}

fn failed_index(failed: &Arc<Mutex<Option<u32>>>) -> Option<u32> {
    failed.lock().ok().and_then(|slot| *slot)
}

/// Run every unit of `world` to completion, resuming an interrupted earlier
/// attempt against the durable store in `store_dir`, and commit the single
/// effect once all units are recorded.
pub async fn recover(
    world: World,
    store_dir: std::path::PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let units = u32::try_from(world.units()).unwrap_or(u32::MAX);
    let run = run_id(&store_dir)?;

    let builder = Host::builder(TASK_NAME).map_err(|_| RecoveryError::NoStore)?;
    let builder = builder
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline);
    let host = HostGuard(builder.build().map_err(|_| RecoveryError::NoStore)?);

    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let body = {
        let world = world.clone();
        let failed = failed.clone();
        move |scope: Scope, _input: ()| work(world.clone(), scope, failed.clone(), units)
    };
    let task_spec = task::task(TASK_NAME, body).map_err(|_| RecoveryError::NoStore)?;

    // `resume` under the directory-derived run id is what makes the first call
    // and every later call the same attempt: recorded units replay, the rest run.
    let mut attempt: u32 = 1;
    loop {
        clear_failed(&failed);
        let report = host.resume(run, &task_spec, ()).await;

        match report.disposition() {
            Disposition::Succeeded => {
                return match report.into_result() {
                    Ok(total) => Ok(total),
                    Err(_) => Err(RecoveryError::Deadline),
                };
            }
            Disposition::DeadlineExceeded => return Err(RecoveryError::Deadline),
            Disposition::Failed | Disposition::Cancelled => {
                if let Some(index) = failed_index(&failed) {
                    // A unit really failed; tear down anything the fan-out left.
                    host.cancel();
                    return Err(RecoveryError::Unit { index });
                }
            }
            Disposition::Refused => {}
        }

        // Not finished, but nothing failed outright: another attempt replays
        // whatever is already recorded and runs only what is missing.
        if attempt >= MAX_ATTEMPTS {
            host.cancel();
            return Err(RecoveryError::Deadline);
        }
        attempt += 1;
    }
}

use std::num::NonZeroUsize;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::{self, UnitError, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{self, FlowError, Scope};
use lgwks_bot::task::{self, Disposition, Host};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

const TENANT: &str = "recovery";
const JOB: &str = "recover";
const EFFECT: &str = "recover";
const RUN: &str = "9f3c1a7d5e2b48061c9a4e7d3b8f2a05";

async fn units(world: World, scope: Arc<Scope>, last: Arc<AtomicU32>) -> Result<u64, FlowError> {
    if !world.ledger().applied(EFFECT) {
        world.ledger().apply(EFFECT);
    }
    let mut total: u64 = 0;
    let mut index: u32 = 0;
    loop {
        last.store(index, Ordering::SeqCst);
        let w = world.clone();
        let inner = scope.clone();
        let step = recovery::unit_step(index);
        let hit: Arc<Mutex<Option<UnitError>>> = Arc::new(Mutex::new(None));
        let sink = hit.clone();
        let outcome = script::remember(&scope, &step, move || async move {
            match w.unit(&inner, index).await {
                Ok(v) => Ok(v),
                Err(e) => {
                    if let Ok(mut g) = sink.lock() {
                        *g = Some(e);
                    }
                    Err(FlowError::failed("unit"))
                }
            }
        })
        .await;
        match outcome {
            Ok(v) => total = total.saturating_add(v),
            Err(_) => {
                let seen = hit.lock().ok().and_then(|mut g| g.take());
                if matches!(seen, Some(UnitError::Unit { .. })) {
                    break;
                }
                return Err(FlowError::failed("unit"));
            }
        }
        index = index.saturating_add(1);
    }
    Ok(total)
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let builder = Host::builder(TENANT).map_err(|_| RecoveryError::NoStore)?;
    let builder = builder
        .run_store(store_dir)
        .map_err(|_| RecoveryError::NoStore)?;
    let host = builder
        .max_concurrent_tasks(NonZeroUsize::new(1).unwrap())
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let last = Arc::new(AtomicU32::new(0));
    let watch = last.clone();
    let job = task::task(JOB, move |scope: Scope, w: World| {
        let watch = watch.clone();
        async move {
            let scope = Arc::new(scope);
            script::within(&scope, "budget", deadline, units(w, scope.clone(), watch)).await
        }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let run = RunId::from_hex(RUN).map_err(|_| RecoveryError::NoStore)?;
    let report = host.resume(run, &job, world).await;

    let timed_out = matches!(
        report.disposition(),
        Disposition::DeadlineExceeded | Disposition::Cancelled
    ) || report.error().map_or(false, |e| {
        matches!(e, FlowError::TimedOut { .. }) || e.is_cancelled()
    });
    if timed_out {
        return Err(RecoveryError::Deadline);
    }
    match report.into_result() {
        Ok(total) => Ok(total),
        Err(_) => Err(RecoveryError::Unit {
            index: last.load(Ordering::SeqCst),
        }),
    }
}

use std::path::PathBuf;
use std::time::Duration;

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{FlowError, Scope, within};
use lgwks_bot::task::{Disposition, Host, task};

const RUN_HEX: &str = "0f0f0f0f0f0f0f0f0f0f0f0f0f0f0f0f0f";
const LEDGER: &str = "recover";

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

async fn drive(world: World, scope: &Scope) -> Result<u64, FlowError> {
    let ledger = world.ledger();
    let mut total: u64 = 0;
    let mut index: u32 = 0;
    loop {
        match world.unit(scope, index).await {
            Ok(value) => total += value,
            Err(_) => break,
        }
        index += 1;
    }
    if !ledger.applied(LEDGER) {
        ledger.apply(LEDGER);
    }
    Ok(total)
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let body = |scope: Scope, input: (World, Duration)| async move {
        let (world, deadline) = input;
        let step = drive(world, &scope);
        within(&scope, "work", deadline, step).await
    };

    let task = task("recover", body).map_err(|_| RecoveryError::NoStore)?;

    let host = Host::builder("recover")
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let run = RunId::from_hex(RUN_HEX).map_err(|_| RecoveryError::NoStore)?;

    let report = host.resume(run, &task, (world, deadline)).await;

    if matches!(
        report.disposition(),
        Disposition::DeadlineExceeded | Disposition::Cancelled
    ) {
        return Err(RecoveryError::Deadline);
    }

    match report.into_result() {
        Ok(total) => Ok(total),
        Err(err) => {
            if err.is_cancelled() || matches!(err, FlowError::TimedOut { .. }) {
                Err(RecoveryError::Deadline)
            } else {
                Err(RecoveryError::NoLedger)
            }
        }
    }
}

//! Durable recovery driver: replays recorded unit bodies, runs whatever is
//! left, and applies the ledger effect exactly once across any number of
//! attempts on the same store directory.

use std::num::NonZeroUsize;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{self, FlowError, Scope};
use lgwks_bot::task::{Disposition, Host};

const TENANT: &str = "recovery";
const TASK_NAME: &str = "recover";
const LEDGER_EFFECT: &str = "recover";
const LEDGER_STEP: &str = "ledger";

/// Every way a recovery attempt can end badly.
#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// What the task body leaves behind for the driver once it is done.
#[derive(Default)]
struct Signals {
    no_ledger: bool,
    out_of_time: bool,
}

/// The shared state the task body writes to.
type Signal = Arc<Mutex<Signals>>;

fn signal(sig: &Signal) -> std::sync::MutexGuard<'_, Signals> {
    sig.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
}

/// Cancels the host when the future driving it is dropped, so no unit body
/// outlives the call that started it.
struct CancelOnDrop {
    host: Host,
}

impl Drop for CancelOnDrop {
    fn drop(&mut self) {
        self.host.cancel();
    }
}

/// Resume the run identified by `store_dir` until the world is exhausted.
///
/// The run identity is derived from the store directory, so the same directory
/// always names the same run and a second call finds the records the first
/// call committed. The task body is built once and shared by the first attempt
/// and every resume.
pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let started = Instant::now();

    let hex = run_hex(&store_dir);
    let run = RunId::from_hex(&hex).map_err(|_| RecoveryError::NoStore)?;

    let signals: Signal = Arc::new(Mutex::new(Signals::default()));
    let body_signals = Arc::clone(&signals);

    // The helper that builds the task body, used by the first attempt and by
    // the resume alike.
    let built = lgwks_bot::task::task(
        TASK_NAME,
        move |scope: Scope, _input: ()| {
            let world = world.clone();
            let signals = Arc::clone(&body_signals);
            let started = started;
            let deadline = deadline;
            async move {
                *signal(&signals) = Signals::default();

                // The effect is guarded twice: the durable record keeps the body
                // from running again on a resume, and the ledger's own probe
                // keeps a second apply out of the book if the record was lost.
                let for_ledger = world.clone();
                let recorded = script::remember(&scope, LEDGER_STEP, move || async move {
                    let ledger = for_ledger.ledger();
                    if !ledger.applied(LEDGER_EFFECT) {
                        ledger.apply(LEDGER_EFFECT);
                    }
                    Ok::<u64, FlowError>(1)
                })
                .await;
                if let Err(err) = recorded {
                    if scope.is_cancelled() {
                        signal(&signals).out_of_time = true;
                    } else {
                        signal(&signals).no_ledger = true;
                    }
                    return Err(err);
                }

                let mut total: u64 = 0;
                let mut index: u32 = 0;
                loop {
                    if scope.is_cancelled() || started.elapsed() >= deadline {
                        signal(&signals).out_of_time = true;
                        return Err(FlowError::failed("recovery deadline"));
                    }

                    match world.unit(&scope, index).await {
                        Ok(value) => {
                            total = total.saturating_add(value);
                            if index == u32::MAX {
                                return Ok(total);
                            }
                            index += 1;
                        }
                        // The world refuses the index past its last unit: the
                        // total of every unit it returned is the recovery.
                        Err(_) => return Ok(total),
                    }
                }
            }
        },
    );
    let task = built.map_err(|_| RecoveryError::NoStore)?;

    let host = Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoStore)?
        .max_concurrent_tasks(NonZeroUsize::new(1).ok_or(RecoveryError::NoStore)?)
        .default_deadline(deadline)
        .progress_capacity(1 << 16)
        .run_store(store_dir.as_path())
        .map_err(|_| RecoveryError::NoStore)?
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let guard = CancelOnDrop { host };

    let report = guard.host.resume(run, &task, ()).await;
    let disposition = report.disposition();
    let (no_ledger, out_of_time) = {
        let sig = signal(&signals);
        (sig.no_ledger, sig.out_of_time)
    };

    if no_ledger {
        return Err(RecoveryError::NoLedger);
    }
    if out_of_time
        || matches!(
            disposition,
            Disposition::DeadlineExceeded | Disposition::Cancelled
        )
    {
        return Err(RecoveryError::Deadline);
    }

    match report.into_result() {
        Ok(total) => Ok(total),
        Err(err) => {
            if err.is_cancelled() || started.elapsed() >= deadline {
                Err(RecoveryError::Deadline)
            } else {
                Err(RecoveryError::NoStore)
            }
        }
    }
}

fn fnv(bytes: &[u8], seed: u64) -> u64 {
    let mut hash = seed;
    for byte in bytes {
        hash ^= *byte as u64;
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

/// 32 lowercase hex characters, stable for a given store directory: the run
/// identity a later attempt uses to find the earlier attempt's records.
fn run_hex(dir: &Path) -> String {
    let text = dir.to_string_lossy();
    let bytes = text.as_bytes();
    let high = fnv(bytes, 0xcbf2_9ce4_8422_2325);
    let low = fnv(bytes, 0x9e37_79b9_7f4a_7c15);
    if high == 0 && low == 0 {
        return "00000000000000000000000000000001".to_string();
    }
    format!("{:016x}{:016x}", high, low)
}

//! Durable recovery of a crash-prone world.
//!
//! Every attempt runs the same task body under the same [`RunId`], against the
//! same durable run store, so a unit whose record was committed on an earlier
//! attempt replays its recorded value instead of running its body again. The
//! single ledger effect is guarded by reading `applied` before `apply`.

use std::path::Path;
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::Arc;
use std::time::Duration;

use ai_task_support::recovery::{UnitError, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{self, FlowError, Scope};
use lgwks_bot::task::{self, Host};

/// Why a recovery attempt did not finish the work.
#[derive(Debug)]
pub enum RecoveryError {
    /// A unit reported a failure and named itself.
    Unit { index: u32 },
    /// The overall deadline passed before the work was finished.
    Deadline,
    /// The durable run store could not be opened, or the host could not be built.
    NoStore,
    /// The ledger effect could not be reached.
    NoLedger,
}

/// Sentinel for "no failing unit was recorded".
const NONE: u32 = u32::MAX;

/// Tenant, task, effect and bound name: all stable, so every attempt shares one path.
const NAME: &str = "recover";

/// Drive the world to completion, resuming whatever an earlier attempt finished.
pub async fn recover(
    world: World,
    store_dir: std::path::PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    // The run identity is derived from the store directory: the same on every
    // attempt, so the resume finds the first attempt's records, and never a
    // fresh random value per call.
    let run = run_id(&store_dir);

    // Without a durable run store a unit's `remember` has nowhere to land, and
    // a resume would re-run every body.
    let host: Host = Host::builder(NAME)
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    // Carries the failing unit's index out of the body, which can only report
    // a located `FlowError`.
    let failed: Arc<AtomicU32> = Arc::new(AtomicU32::new(NONE));

    // The body needs its own handle on the world; `world` itself stays here so
    // the ledger can be read once the attempt is over.
    let driven = world.clone();
    let mark = Arc::clone(&failed);

    // One body, reused by the first attempt and by every resume.
    let job = task::task(NAME, move |scope: Scope, _input: ()| {
        let world = driven.clone();
        let failed = Arc::clone(&mark);
        async move { attempt(&world, &scope, deadline, &failed).await }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    // `resume` is the first attempt when nothing was recorded yet, and a
    // replay of the records an earlier attempt committed otherwise.
    match host.resume(run, &job, ()).await.into_result() {
        Ok(total) => {
            if world.ledger().applies() == 0 {
                return Err(RecoveryError::NoLedger);
            }
            Ok(total)
        }
        Err(_) => match Arc::clone(&failed).swap(NONE, Ordering::SeqCst) {
            NONE => Err(RecoveryError::Deadline),
            index => Err(RecoveryError::Unit { index }),
        },
    }
}

/// The body: every unit of the world, then the effect, once.
async fn attempt(
    world: &World,
    scope: &Scope,
    deadline: Duration,
    failed: &AtomicU32,
) -> Result<u64, FlowError> {
    // `within` races the sweep against the deadline and against cancellation,
    // dropping every unit body on either, so none outlives the call.
    let total = script::within(scope, "sweep", deadline, sweep(world, scope, failed)).await?;

    // `apply` refuses nothing, so reading `applied` first is the only way to
    // keep this at exactly one apply across every attempt.
    let ledger = world.ledger();
    if !ledger.applied(NAME) {
        ledger.apply(NAME);
    }

    Ok(total)
}

/// Run the units in index order until the world runs out of them. Each unit
/// records its own value, so a resumed attempt replays instead of redoing.
async fn sweep(world: &World, scope: &Scope, failed: &AtomicU32) -> Result<u64, FlowError> {
    let mut total: u64 = 0;
    let mut index: u32 = 0;
    loop {
        match world.unit(scope, index).await {
            Ok(value) => {
                total = total.saturating_add(value);
                index = match index.checked_add(1) {
                    Some(next) => next,
                    None => return Ok(total),
                };
            }
            // The world named the unit asked for, or one past it: there is no
            // such unit, so the sweep is done.
            Err(UnitError::Unit { index: named }) if named >= index => return Ok(total),
            // It named an earlier unit, so that unit is the one that failed.
            Err(UnitError::Unit { index: named }) => {
                failed.store(named, Ordering::SeqCst);
                return Err(FlowError::failed(format!("unit {named} failed")));
            }
            // Anything else the world can say means it has no unit here.
            Err(_) => return Ok(total),
        }
    }
}

/// 32 lowercase hex characters derived from the store directory, never all zero.
fn run_id(store_dir: &Path) -> RunId {
    let bytes = store_dir.to_string_lossy().into_owned().into_bytes();
    let mut low: u64 = 0xcbf2_9ce4_8422_2325;
    let mut high: u64 = 0x9e37_79b9_7f4a_7c15;
    for (position, byte) in bytes.iter().enumerate() {
        low ^= u64::from(*byte).wrapping_add(position as u64);
        low = low.wrapping_mul(0x0000_0100_0000_01b3);
        high = (high ^ low.rotate_left(31)).wrapping_mul(0xff51_afd7_ed55_8ccd);
        high ^= high >> 29;
    }
    if low == 0 && high == 0 {
        low = 1;
    }

    let text = format!("{:016x}{:016x}", low, high);
    match RunId::from_hex(&text) {
        Ok(run) => run,
        Err(_) => unreachable!("a derived run id is 32 lowercase hex characters"),
    }
}

//! Durable, resumable recovery over a world of units.

use std::future::Future;
use std::ops::Range;
use std::path::{Path, PathBuf};
use std::pin::Pin;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{at_most, each, within, FlowError, Scope};
use lgwks_bot::task::{task, Host, Task};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

type UnitBody = Pin<Box<dyn Future<Output = Result<u64, FlowError>> + Send + 'static>>;

const LEDGER_EFFECT: &str = "recover";
const TASK_NAME: &str = "recover";
const TENANT: &str = "recovery";
const FALLBACK_RUN: &str = "00000000000000000000000000000001";
const FAN_OUT: usize = 8;

/// A run identity derived from the store location: the same store always
/// yields the same run, so a later attempt finds the earlier records.
fn run_id(store_dir: &Path) -> RunId {
    let mut low: u64 = 0xcbf2_9ce4_8422_2325;
    let mut high: u64 = 0x9ae1_6a3b_2f90_404f;
    for byte in store_dir.to_string_lossy().as_bytes() {
        low ^= u64::from(*byte);
        low = low.wrapping_mul(0x0000_0100_0000_01b3);
        high = high.wrapping_add(u64::from(*byte)).wrapping_mul(0x9e37_79b9_7f4a_7c15);
        high ^= high >> 29;
    }
    let text = format!("{:016x}{:016x}", low, high);
    match RunId::from_hex(&text) {
        Ok(run) => run,
        Err(_) => match RunId::from_hex(FALLBACK_RUN) {
            Ok(run) => run,
            Err(_) => unreachable!("a fixed, non-zero run id is always parseable"),
        },
    }
}

/// A unit failure has to travel out through `FlowError`, so the index it
/// names is parked in a shared slot and read back once the task has settled.
fn classify(_error: FlowError, failure: &Arc<Mutex<Option<u32>>>) -> RecoveryError {
    match failure.lock() {
        Ok(seen) => match *seen {
            Some(index) => RecoveryError::Unit { index },
            None => RecoveryError::Deadline,
        },
        Err(_) => RecoveryError::Deadline,
    }
}

/// The task body, built once and reused by the first attempt and every resume.
fn build_task(
    world: World,
    units: Range<u32>,
    failure: Arc<Mutex<Option<u32>>>,
    deadline: Duration,
) -> Result<Task<impl Fn(Scope, ()) -> UnitBody + Send + Sync + 'static>, RecoveryError> {
    let fan_out = at_most(FAN_OUT).map_err(|_| RecoveryError::NoStore)?;

    let body = move |scope: Scope, _input: ()| -> UnitBody {
        let world = world.clone();
        let units = units.clone();
        let failure = failure.clone();
        Box::pin(async move {
            let work = async {
                let fan_world = world.clone();
                let fan_failure = failure.clone();
                let values = each(
                    &scope,
                    "units",
                    Some(fan_out),
                    units,
                    move |step, index| {
                        let world = fan_world.clone();
                        let failure = fan_failure.clone();
                        async move {
                            match world.unit(&step, index).await {
                                Ok(value) => Ok(value),
                                Err(_) => {
                                    if let Ok(mut seen) = failure.lock() {
                                        if seen.is_none() {
                                            *seen = Some(index);
                                        }
                                    }
                                    Err(FlowError::failed("unit failed"))
                                }
                            }
                        }
                    },
                )
                .await?;

                let total: u64 = values.into_iter().sum();

                let ledger = world.ledger();
                if !ledger.applied(LEDGER_EFFECT) {
                    ledger.apply(LEDGER_EFFECT);
                }
                Ok::<u64, FlowError>(total)
            };
            within(&scope, "work", deadline, work).await
        })
    };

    task(TASK_NAME, body).map_err(|_| RecoveryError::NoStore)
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let units: Range<u32> = world.units();
    let steps = units.len().saturating_mul(2).saturating_add(16);
    let failure = Arc::new(Mutex::new(None));

    let one = match std::num::NonZeroUsize::new(1) {
        Some(one) => one,
        None => return Err(RecoveryError::NoStore),
    };

    let builder = Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoStore)?
        .max_concurrent_tasks(one)
        .progress_capacity(steps);
    let builder = if deadline.is_zero() {
        builder
    } else {
        builder.default_deadline(deadline)
    };

    let host = builder
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let task = build_task(world, units, failure.clone(), deadline)?;
    let report = host.resume(run_id(&store_dir), &task, ()).await;

    match report.into_result() {
        Ok(total) => Ok(total),
        Err(error) => Err(classify(error, &failure)),
    }
}

use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::Arc;
use std::time::Duration;

use ai_task_support::recovery::{self, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{remember, within, FlowError, Scope};
use lgwks_bot::task::{self, Disposition, Host};

/// Failures `recover` can report.
#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// A stable run identity derived from the store directory, so that every
/// attempt at the same `store_dir` finds the records the previous one wrote.
fn run_id(store_dir: &Path) -> Option<RunId> {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for byte in store_dir.to_string_lossy().as_bytes() {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    let low = hash;
    let high = hash
        .rotate_left(32)
        .wrapping_add(0x9e37_79b9_7f4a_7c15);
    RunId::from_hex(&format!("{low:016x}{high:016x}")).ok()
}

/// One unit per step, each wrapped in `remember` so a completed unit replays
/// its recorded value instead of running its body again. The loop stops at the
/// first index the world refuses: that is the end of the world.
async fn units(world: &World, scope: &Scope, seen: &AtomicU32) -> Result<u64, FlowError> {
    let mut total: u64 = 0;
    let mut index: u32 = 0;
    loop {
        let step = recovery::unit_step(index);
        let outcome = remember(scope, &step, move || async move {
            match world.unit(scope, index).await {
                Ok(value) => Ok(value),
                Err(_) => Err(FlowError::failed("no such unit")),
            }
        })
        .await;

        match outcome {
            Ok(value) => {
                total = total.saturating_add(value);
                index += 1;
                seen.store(index, Ordering::SeqCst);
            }
            Err(_) => break,
        }
    }
    Ok(total)
}

/// The task body, shared by the first attempt and the resume.
async fn drive(
    world: &World,
    scope: &Scope,
    deadline: Duration,
    seen: &AtomicU32,
) -> Result<u64, FlowError> {
    let total = within(scope, "work", deadline, units(world, scope, seen)).await?;

    let ledger = world.ledger();
    remember(scope, "effect", || async move {
        if !ledger.applied("recover") {
            ledger.apply("recover");
        }
        Ok::<u64, FlowError>(0)
    })
    .await?;

    Ok(total)
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let run = run_id(&store_dir).ok_or(RecoveryError::NoStore)?;

    let host = Host::builder("recover")
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let seen = Arc::new(AtomicU32::new(0));
    let unit_task = task::task("recover", {
        let seen = seen.clone();
        move |scope: Scope, _input: ()| {
            let world = world.clone();
            let seen = seen.clone();
            async move { drive(&world, &scope, deadline, &seen).await }
        }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let report = host.resume(run, &unit_task, ()).await;
    let disposition = report.disposition();

    match report.into_result() {
        Ok(total) => Ok(total),
        Err(error) => {
            let unfinished = matches!(disposition, Disposition::DeadlineExceeded)
                || error.is_cancelled()
                || matches!(error, FlowError::TimedOut { .. });
            if unfinished {
                Err(RecoveryError::Deadline)
            } else {
                Err(RecoveryError::Unit {
                    index: seen.load(Ordering::SeqCst),
                })
            }
        }
    }
}
